package com.lexia.legalassistant.data.repository

/**
 * Registro oficial estatutario de artículos clave de la Ley Federal del Trabajo (LFT).
 * Reglamentaria del Apartado A del Artículo 123 de la Constitución Política de los Estados Unidos Mexicanos.
 * Texto DOF Vigente con las reformas de Justicia Laboral, Teletrabajo y Vacaciones Dignas.
 */
object LftStatutoryData {

    data class ArticleMeta(
        val title: String,
        val category: String,
        val summary: String
    )

    val articles: Map<Int, ArticleMeta> = mapOf(
        1 to ArticleMeta("Ámbito de Aplicación de la Ley Federal del Trabajo", "Principios Generales", "La presente Ley es de observancia general en toda la República y rige las relaciones de trabajo comprendidas en el artículo 123, Apartado A, de la Constitución."),
        2 to ArticleMeta("Normas del Trabajo y Trabajo Digno o Decente", "Principios Generales", "Las normas del trabajo tienden a conseguir el equilibrio entre los factores de la producción y la justicia social, propiciando el trabajo digno o decente en todas las relaciones laborales."),
        3 to ArticleMeta("El Trabajo como Deber y Derecho Social: No Discriminación", "Principios Generales", "El trabajo es un derecho y un deber social. No es artículo de comercio y exige respeto para las libertades y dignidad de quien lo presta. Prohíbe discriminación por género, edad, discapacidad, raza o religión."),
        4 to ArticleMeta("Irrenunciabilidad de Derechos Laborales", "Principios Generales", "No se podrá impedir el trabajo a ninguna persona ni que se dedique a la profesión, industria o comercio que le acomode, siendo lícitos. Los derechos laborales consagrados son irrenunciables."),
        18 to ArticleMeta("Principio Pro Operario en la Interpretación de la Ley", "Principios Generales", "En la interpretación de las normas de trabajo se tomarán en consideración sus finalidades. En caso de duda, prevalecerá la interpretación más favorable al trabajador (in dubio pro operario)."),
        20 to ArticleMeta("Definición de Relación y Contrato Individual de Trabajo", "Relación Laboral", "Se entiende por relación de trabajo la prestación de un trabajo personal subordinado a una persona, mediante el pago de un salario. Contrato individual de trabajo es aquel por virtud del cual una persona se obliga a prestar a otra un trabajo personal subordinado."),
        21 to ArticleMeta("Presunción Legal de la Relación de Trabajo", "Relación Laboral", "Se presumen la existencia del contrato y de la relación de trabajo entre el que presta un trabajo personal y el que lo recibe, arrojando la carga de la prueba en contrario al patrón."),
        25 to ArticleMeta("Requisitos Esenciales del Contrato Escrito de Trabajo", "Contratación", "El escrito en que consten las condiciones de trabajo deberá contener: datos de las partes, servicios prestados, lugar de trabajo, duración de la jornada, forma y monto del salario, y capacitación."),
        35 to ArticleMeta("Modalidades de Contratación: Tiempo Determinado e Indeterminado", "Estabilidad Laboral", "Las relaciones de trabajo pueden ser para obra o tiempo determinado, por temporada o por tiempo indeterminado y, en su caso, podrá estar sujeto a prueba o a capacitación inicial."),
        39 to ArticleMeta("Periodo de Prueba y Capacitación Inicial (39-A a 39-F)", "Estabilidad Laboral", "Los periodos de prueba pueden extenderse de 30 hasta 180 días tratándose de puestos de dirección o gerencia, garantizando la seguridad social del trabajador durante su transcurso."),
        47 to ArticleMeta("Causales Taxativas de Rescisión Laboral sin Responsabilidad Patronal", "Rescisión Laboral", "Son causas de rescisión de la relación de trabajo, sin responsabilidad para el patrón: engaño con certificados falsos, faltas de probidad u honradez, violencia contra compañeros o el patrón, daños materiales dolosos, y más de tres faltas injustificadas en 30 días."),
        48 to ArticleMeta("Despido Injustificado, Indemnización Constitucional y Salarios Caídos", "Rescisión Laboral", "El trabajador podrá solicitar ante el Tribunal la reinstalación o que se le indemnice con el importe de tres meses de salario. Si el patrón no comprueba la causa de la rescisión, el trabajador tendrá derecho al pago de los salarios vencidos computados desde la fecha del despido hasta por un período máximo de doce meses; si no se ha resuelto el juicio, se pagará un interés del 2% mensual capitalizable."),
        51 to ArticleMeta("Causales de Rescisión Laboral sin Responsabilidad para el Trabajador", "Rescisión Laboral", "El trabajador puede rescindir la relación laboral por engaño patronal respecto a las condiciones de trabajo, faltas de probidad, reducción injustificada del salario, exigencia de actos ilícitos o peligro grave para la salud."),
        56 to ArticleMeta("Principio de Igualdad de Condiciones de Trabajo", "Condiciones Laborales", "Las condiciones de trabajo basadas en el principio de igualdad sustantiva no podrán establecer diferencias por motivo de origen étnico o nacional, género, edad, discapacidad o condición social."),
        61 to ArticleMeta("Duración Máxima de las Jornadas de Trabajo", "Jornada de Trabajo", "La duración máxima de la jornada será: ocho horas la diurna (entre las 6:00 y las 20:00 horas), siete horas la nocturna (entre las 20:00 y las 6:00 horas) y siete horas y media la mixta."),
        67 to ArticleMeta("Remuneración de Horas Extraordinarias de Trabajo", "Jornada de Trabajo", "Las horas de trabajo extraordinario se pagarán con un ciento por ciento más del salario que corresponda a las horas de la jornada ordinaria (horas dobles)."),
        68 to ArticleMeta("Límite de Horas Extras y Horas Triples", "Jornada de Trabajo", "La prolongación del tiempo extraordinario que exceda de nueve horas a la semana obliga al patrón a pagar al trabajador el tiempo excedente con un doscientos por ciento más del salario ordinario (horas triples)."),
        69 to ArticleMeta("Día de Descanso Semanal Obligatorio y Pago del Salario", "Días de Descanso", "Por cada seis días de trabajo disfrutará el trabajador de un día de descanso, por lo menos, con goce de salario íntegro, procurando que sea el día domingo."),
        71 to ArticleMeta("Prima Dominical del Veinticinco por Ciento", "Días de Descanso", "Los trabajadores que presten servicio en día domingo tendrán derecho a una prima adicional de un veinticinco por ciento, por lo menos, sobre el salario de los días ordinarios de trabajo."),
        74 to ArticleMeta("Catálogo de Días de Descanso Obligatorio por Ley", "Días de Descanso", "Son días de descanso obligatorio: 1 de enero, primer lunes de febrero (5 de feb), tercer lunes de marzo (21 de mar), 1 de mayo, 16 de septiembre, tercer lunes de noviembre (20 de nov), 1 de octubre cada seis años y 25 de diciembre."),
        76 to ArticleMeta("Régimen de Vacaciones Dignas y Plazos Legales", "Vacaciones", "Las personas trabajadoras que tengan más de un año de servicios disfrutarán de un periodo anual de vacaciones pagadas, que en ningún caso podrá ser inferior a doce días laborables, y que aumentará en dos días laborables, hasta llegar a veinte, por cada año subsecuente de servicios."),
        80 to ArticleMeta("Prima Vacacional Mínima Legal del Veinticinco por Ciento", "Vacaciones", "Los trabajadores tendrán derecho a una prima no menor de veinticinco por ciento sobre los salarios que les correspondan durante el período de vacaciones."),
        82 to ArticleMeta("Concepto Legal de Salario", "Salario", "Salario es la retribución que debe pagar el patrón al trabajador por su trabajo."),
        84 to ArticleMeta("Integración del Salario para Indemnizaciones", "Salario", "El salario se integra con los pagos hechos en efectivo por cuota diaria, gratificaciones, percepción, habitación, primas, comisiones, prestaciones en especie y cualquiera otra cantidad que se entregue al trabajador por su trabajo."),
        87 to ArticleMeta("Derecho al Aguinaldo Anual Obligatorio", "Salario", "Los trabajadores tendrán derecho a un aguinaldo anual que deberá pagarse antes del día veinte de diciembre, equivalente a quince días de salario, por lo menos. Quienes no hayan cumplido el año tendrán derecho a la parte proporcional."),
        90 to ArticleMeta("Concepto de Salario Mínimo Legal e Inembargabilidad", "Salario Mínimo", "Salario mínimo es la cantidad menor que debe recibir en efectivo el trabajador por los servicios prestados en una jornada de trabajo. Debe ser suficiente para satisfacer las necesidades normales de un jefe de familia en el orden material, social y cultural."),
        97 to ArticleMeta("Prohibición General de Descuentos al Salario Mínimo", "Protección al Salario", "Los salarios mínimos no podrán ser objeto de compensación, descuento o reducción, salvo en los casos de pensiones alimenticias decretadas por la autoridad judicial competente."),
        117 to ArticleMeta("Participación de los Trabajadores en las Utilidades (PTU)", "Reparto de Utilidades", "Los trabajadores participarán en las utilidades de las empresas de conformidad con el porcentaje que determine la Comisión Nacional para la Participación de los Trabajadores en las Utilidades de las Empresas (fijado en 10%)."),
        122 to ArticleMeta("Plazo Legal para el Pago de Utilidades a Trabajadores", "Reparto de Utilidades", "El reparto de utilidades entre los trabajadores deberá efectuarse dentro de los sesenta días siguientes a la fecha en que deba pagarse el impuesto anual (a más tardar en mayo para personas morales y junio para personas físicas)."),
        127 to ArticleMeta("Tope Máximo y Reglas Especiales de Pago de PTU", "Reparto de Utilidades", "El monto de la participación de utilidades tendrá como límite máximo tres meses del salario del trabajador o el promedio de la participación recibida en los últimos tres años, aplicándose el monto más favorable."),
        132 to ArticleMeta("Obligaciones Patronales Fundamentales", "Obligaciones", "Pagar los salarios e indemnizaciones, proporcionar herramientas y útiles de trabajo, conceder licencias de paternidad (5 días laborables con goce de sueldo) y capacitar al personal."),
        133 to ArticleMeta("Prohibiciones Expresas a los Patrones", "Obligaciones", "Queda prohibido a los patrones: negarse a aceptar trabajadores por razón de origen étnico o género, exigir certificados de no embarazo, realizar o tolerar acoso sexual, y retener salarios indebidamente."),
        162 to ArticleMeta("Derecho a la Prima de Antigüedad", "Antigüedad", "Los trabajadores de planta tienen derecho a una prima de antigüedad consistente en doce días de salario por cada año de servicios, con un tope máximo del doble del salario mínimo general."),
        170 to ArticleMeta("Derechos Tutelares de Madres Trabajadoras e Incapacidad", "Protección a la Maternidad", "Las madres trabajadoras disfrutarán de un descanso de seis semanas anteriores y seis semanas posteriores al parto con goce de salario íntegro, dos descansos extraordinarios por día para lactancia y estabilidad en el empleo."),
        311 to ArticleMeta("Concepto de Teletrabajo / Home Office", "Teletrabajo", "Teletrabajo es una forma de organización laboral subordinada que consiste en el desempeño de actividades remuneradas en lugares distintos al establecimiento del patrón mediante las tecnologías de la información."),
        330 to ArticleMeta("Derecho a la Desconexión Digital y Gastos de Teletrabajo (330-A a 330-K)", "Teletrabajo", "El patrón debe proporcionar los insumos informáticos (computadora, silla ergonómica), asumir los costos de electricidad e internet, y respetar estrictamente el derecho del trabajador a la desconexión digital al término de su jornada."),
        356 to ArticleMeta("Libertad de Asociación y Sindicatos", "Derecho Colectivo", "Sindicato es la asociación de trabajadores o patrones, constituida para el estudio, mejoramiento y defensa de sus respectivos intereses."),
        386 to ArticleMeta("Definición de Contrato Colectivo de Trabajo", "Contrato Colectivo", "Contrato colectivo de trabajo es el convenio celebrado entre uno o varios sindicatos de trabajadores y uno o varios patrones con el objeto de establecer las condiciones de trabajo."),
        390 to ArticleMeta("Constancia de Representatividad y Legitimación de Contratos", "Contrato Colectivo", "Para celebrar por primera vez un Contrato Colectivo de Trabajo es indispensable que el sindicato obtenga previamente la Constancia de Representatividad emitida por el Centro Federal de Conciliación con el respaldo del 30% de los trabajadores."),
        440 to ArticleMeta("Definición y Naturaleza Jurídica de la Huelga", "Derecho de Huelga", "Huelga es la suspensión temporal del trabajo llevada a cabo por una coalición de trabajadores en defensa de sus derechos laborales colectivos."),
        473 to ArticleMeta("Concepto de Riesgos de Trabajo", "Riesgos de Trabajo", "Riesgos de trabajos son los accidentes y enfermedades a que están expuestos los trabajadores en ejercicio o con motivo del trabajo."),
        474 to ArticleMeta("Definición de Accidente de Trabajo", "Riesgos de Trabajo", "Accidente de trabajo es toda lesión orgánica o perturbación funcional producida repentinamente en ejercicio o con motivo del trabajo, cualesquiera que sean el lugar y el tiempo en que se preste, incluyendo los de trayecto (domicilio-trabajo)."),
        475 to ArticleMeta("Definición de Enfermedad de Trabajo", "Riesgos de Trabajo", "Enfermedad de trabajo es todo estado patológico derivado de la acción continuada de una causa que tenga su origen o motivo en el trabajo o en el medio en que el trabajador preste sus servicios."),
        684 to ArticleMeta("Procedimiento Obligatorio de Conciliación Prejudicial (684-A a 684-U)", "Justicia Laboral", "Antes de acudir a los Tribunales Laborales, los trabajadores y patrones deberán asistir a la instancia conciliatoria obligatoria ante el Centro Federal de Conciliación y Registro Laboral o Centros locales en un plazo que no excederá de 45 días naturales."),
        870 to ArticleMeta("Procedimiento Ordinario ante Tribunales Laborales del Poder Judicial", "Justicia Laboral", "El procedimiento ordinario laboral ante los Tribunales del Poder Judicial consta de fase escrita (demanda, contestación, réplica y contrarréplica), Audiencia Preliminar de depuración procesal y Audiencia de Juicio Oral concentrada.")
    )
}
